package ly.com.tahaben.notification_filter_data.local.preferences

import ly.com.tahaben.notification_filter_domain.delivery.DeliveryBudgetState
import ly.com.tahaben.notification_filter_domain.model.NotificationSchedulePeriod
import ly.com.tahaben.notification_filter_domain.schedule.*
import org.json.JSONArray
import org.json.JSONObject
import java.time.LocalDate

/** Mates the existing sh/sm/eh/em/b preference format with the additive version-1 snapshot. */
object ScheduleCodec {
    fun decodeSchedule(json: String): List<NotificationSchedulePeriod> = decodeWindows(JSONArray(json))
    private fun decodeWindows(windows: JSONArray): List<NotificationSchedulePeriod> = (0 until windows.length()).map {
        val window = windows.getJSONObject(it)
        NotificationSchedulePeriod(window.getInt("sh"), window.getInt("sm"), window.getInt("eh"), window.getInt("em"), window.getInt("b"))
    }
    private fun windows(schedule: List<NotificationSchedulePeriod>): JSONArray = JSONArray().apply {
        schedule.forEach { window -> put(JSONObject().apply {
            put("sh", window.startHour); put("sm", window.startMinute); put("eh", window.endHour); put("em", window.endMinute); put("b", window.budgetPoints)
        }) }
    }
    fun encodeSchedule(schedule: List<NotificationSchedulePeriod>): String = windows(schedule).toString()
    fun encode(snapshot: ScheduleSnapshot): String = JSONObject().apply {
        put("version", 1)
        put("repeating", windows(snapshot.book.repeating))
        put("dated", JSONObject().apply { snapshot.book.dated.forEach { (date, schedule) -> put(date.toString(), windows(schedule)) } })
        put("budget", JSONObject().apply {
            put("spent", snapshot.budget.spentPoints); put("start", snapshot.budget.periodStartMinute)
            put("hourly", snapshot.budget.hourlyCount); put("hour", snapshot.budget.passthroughWindowHour); put("day", snapshot.budget.localDay); put("accounting", snapshot.budget.accountingId)
        })
    }.toString()
    fun decode(json: String): ScheduleSnapshot {
        val root = JSONObject(json)
        require(root.getInt("version") == 1) { "Unsupported schedule storage version" }
        val dated = root.getJSONObject("dated")
        val budget = root.getJSONObject("budget")
        return ScheduleSnapshot(ScheduleBook(decodeWindows(root.getJSONArray("repeating")), dated.keys().asSequence().associate {
            LocalDate.parse(it) to decodeWindows(dated.getJSONArray(it))
        }), DeliveryBudgetState(budget.getInt("spent"), budget.getInt("start"), budget.getInt("hourly"), budget.getInt("hour"), budget.getString("day"), budget.optString("accounting", "")))
    }
}
package ly.com.tahaben.notification_filter_data.local.preferences

import android.content.SharedPreferences
import ly.com.tahaben.notification_filter_domain.schedule.AutomationCredentialOwner
import java.security.MessageDigest
import java.security.SecureRandom
import javax.inject.Inject
import javax.inject.Singleton

/** Local opt-in credential owner. UI may copy/rotate/revoke it; no credential enters logs or tracing. */
@Singleton
class ScheduleAutomationCredentials @Inject constructor(private val preferences: SharedPreferences) : AutomationCredentialOwner {
    override fun isEnabled(): Boolean = preferences.getBoolean(ENABLED, false)
    override fun matches(presented: String?): Boolean {
        val saved = credential() ?: return false
        if (presented?.length != 64) return false
        return MessageDigest.isEqual(saved.toByteArray(Charsets.UTF_8), presented.toByteArray(Charsets.UTF_8))
    }
    override fun credential(): String? = preferences.getString(CREDENTIAL, null)
    override fun rotate(): String {
        val bytes = ByteArray(32).also { SecureRandom().nextBytes(it) }
        val credential = bytes.joinToString("") { "%02x".format(it.toInt() and 255) }
        check(preferences.edit().putString(CREDENTIAL, credential).commit())
        return credential
    }
    override fun setEnabled(enabled: Boolean) {
        require(!enabled || credential() != null) { "Create an automation credential before enabling" }
        check(preferences.edit().putBoolean(ENABLED, enabled).commit())
    }
    override fun revoke() { check(preferences.edit().putBoolean(ENABLED, false).remove(CREDENTIAL).commit()) }
    companion object {
        private const val ENABLED = "notification_automation_enabled_v1"
        private const val CREDENTIAL = "notification_automation_credential_v1"
    }
}
package ly.com.tahaben.notification_filter_domain.schedule

import ly.com.tahaben.notification_filter_domain.delivery.DeliveryBudgetState
import ly.com.tahaben.notification_filter_domain.model.NotificationSchedulePeriod
import java.time.Clock
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneId

enum class ScheduleMode { REPEATING, DATED }

/** The repeating schedule plus single-date overrides. Other dates use [repeating]. */
data class ScheduleBook(
    val repeating: List<NotificationSchedulePeriod> = NotificationSchedulePeriod.DEFAULT_SCHEDULE,
    val dated: Map<LocalDate, List<NotificationSchedulePeriod>> = emptyMap(),
) {
    fun scheduleFor(date: LocalDate): List<NotificationSchedulePeriod> = dated[date] ?: repeating

    /** The schedule in force at [instant] on the phone's wall clock in [zone]. */
    fun scheduleAt(instant: Instant, zone: ZoneId): List<NotificationSchedulePeriod> = scheduleFor(instant.atZone(zone).toLocalDate())
}

/** Schedule and spend are committed together so an edit can never expose zero spend in between. */
data class ScheduleSnapshot(val book: ScheduleBook, val budget: DeliveryBudgetState)

interface ScheduleBookStore {
    suspend fun read(): ScheduleSnapshot

    /** All-or-nothing. */
    suspend fun commit(snapshot: ScheduleSnapshot)
}

data class ScheduleWrite(
    val schedule: List<NotificationSchedulePeriod>,
    val mode: ScheduleMode = ScheduleMode.REPEATING,
    val date: LocalDate? = null,
)

enum class ScheduleWriteError { INVALID_SCHEDULE, DATE_REQUIRED, DATE_NOT_ALLOWED, STORAGE_REPAIR_REQUIRED }

sealed interface ScheduleWriteResult {
    data object Accepted : ScheduleWriteResult
    data class Rejected(
        val error: ScheduleWriteError,
        val violations: List<ScheduleViolation> = emptyList(),
    ) : ScheduleWriteResult
}

/** CLAIM(edit-preserves-spend): rebase current spend at acceptance, not on drag frames [ScheduleWriteTest]. */
class ScheduleWriter(
    private val store: ScheduleBookStore,
    private val clock: Clock,
    private val gate: ly.com.tahaben.notification_filter_domain.delivery.DeliveryGate = ly.com.tahaben.notification_filter_domain.delivery.DeliveryGate(),
    private val minuteNow: (() -> Int)? = null,
) {
    suspend fun write(write: ScheduleWrite): ScheduleWriteResult = gate.run {
        val violations = DaySchedule.validate(write.schedule)
        if (violations.isNotEmpty()) return@run ScheduleWriteResult.Rejected(ScheduleWriteError.INVALID_SCHEDULE, violations)
        if (write.mode == ScheduleMode.DATED && write.date == null) return@run ScheduleWriteResult.Rejected(ScheduleWriteError.DATE_REQUIRED)
        if (write.mode == ScheduleMode.REPEATING && write.date != null) return@run ScheduleWriteResult.Rejected(ScheduleWriteError.DATE_NOT_ALLOWED)
        val now = clock.instant().atZone(clock.zone)
        val today = now.toLocalDate()
        val minute = minuteNow?.invoke() ?: (now.hour * 60 + now.minute)
        val previous = try { store.read() } catch (_: ScheduleReadException) {
            return@run ScheduleWriteResult.Rejected(ScheduleWriteError.STORAGE_REPAIR_REQUIRED)
        }
        val policy = ly.com.tahaben.notification_filter_domain.delivery.NotificationDeliveryPolicy
        val activeBudget = policy.normalizeBudget(previous.budget, previous.book.scheduleFor(today), minute, today.toString())
        // CLAIM(dated-bounded): a date before today can never apply again, so each write drops them; the date being
        // written is kept even if it is past, so an accepted write is always visible [ScheduleWriteTest].
        val keptDated = previous.book.dated.filterKeys { it >= today }
        val book = when (write.mode) {
            ScheduleMode.REPEATING -> previous.book.copy(repeating = write.schedule.toList(), dated = keptDated - today)
            ScheduleMode.DATED -> previous.book.copy(dated = keptDated + (write.date!! to write.schedule.toList()))
        }
        val newActive = policy.findActivePeriod(book.scheduleFor(today), minute)
        store.commit(ScheduleSnapshot(book, activeBudget.copy(periodStartMinute = newActive?.startMinuteOfDay ?: -1)))
        ScheduleWriteResult.Accepted
    }
}

